'use strict';
const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'..'),out=path.join(root,'outputs/retirement-20years-20261011'),s=JSON.parse(fs.readFileSync(path.join(out,'summary.json')));
const visualKeys=['season','qualityPct','controlQualityPct','openingPlayers','closingPlayers','expenses','salaries','youthFunding','generated','promoted','retired'];
const visualRows=rows=>rows.map(r=>Object.fromEntries(visualKeys.map(k=>[k,Math.round(r[k]*1000)/1000])));
const visual={latest:s.latest,total:visualRows(s.total),countries:s.countries.map(c=>({country:c.country,label:c.label,series:visualRows(c.series)}))};
const html=`<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
*{box-sizing:border-box}body{margin:0;color:var(--foreground,#222);font:14px var(--font-sans,system-ui);background:transparent}p{line-height:1.5}.muted{color:var(--muted-foreground,#667)}.controls{display:flex;flex-wrap:wrap;gap:12px;margin:18px 0}label{display:grid;gap:5px}select{font:inherit;padding:8px;color:inherit;background:var(--card,#fff);border:1px solid var(--border,#ccc);border-radius:7px}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:18px 0}.stats b{display:block;font-size:24px;line-height:1.2}.stats span{font-size:12px;color:var(--muted-foreground,#667)}svg{display:block;width:100%;height:260px;overflow:visible}.legend{display:flex;gap:20px;flex-wrap:wrap;font-size:12px}.legend i{display:inline-block;width:20px;height:3px;vertical-align:middle;margin-right:6px}.table{overflow-x:auto;margin-top:20px}table{border-collapse:collapse;width:100%;white-space:nowrap;font-variant-numeric:tabular-nums;font-size:12px}th,td{padding:8px;text-align:right;border-bottom:1px solid var(--border,#ddd)}th:first-child,td:first-child{text-align:left;position:sticky;left:0;background:var(--background,#fff)}th{font-weight:600;color:var(--muted-foreground,#667)}@media(max-width:450px){.stats{gap:8px}.stats b{font-size:20px}.controls label{flex:1}select{width:100%}}
</style></head><body><p><strong>Karriereenden über ${s.latest} Saisons</strong><br><span class="muted">33 Jahre: 40 %, jährlich +10 Prozentpunkte. Drei vergleichbare Welten · 95 KI-Ligavereine je Welt.</span></p>
<div class="controls"><label>Auswertung<select id="country"><option value="all">Alle Länder</option>${s.countries.map(c=>`<option value="${c.country}">${c.label}</option>`).join('')}</select></label><label>Verlauf<select id="metric"><option value="quality">Kaderstärke</option><option value="players">Spielerzahl</option><option value="costs">Ausgaben</option><option value="youth">Nachwuchs</option></select></label></div><div class="stats" id="stats"></div><svg id="chart" viewBox="0 0 700 260" role="img" aria-label="Saisonverlauf"></svg><div id="legend" class="legend"></div><p id="note" class="muted"></p><div class="table"><table><thead><tr><th>Saison</th><th>Stärke¹</th><th>Spieler Start → Ende</th><th>Ausgaben²</th><th>Gehälter²</th><th>Förderung²</th><th>Erzeugt³</th><th>Übernommen³</th><th>Abschiede³</th></tr></thead><tbody id="rows"></tbody></table></div><p class="muted" style="font-size:12px">¹ Gegenüber dem Kader bei Karrierebeginn, nach Abschieden. ² Credits je Verein und Saison, brutto. ³ Anzahl je Welt bzw. Land, Mittelwert aus drei Welten. Übernahmen umfassen auch ältere Jahrgänge und den anfänglichen Nachwuchspool.</p>
<script>const data=${JSON.stringify(visual).replace(/</g,'\\u003c')};const fmt=(n,d=1)=>(Math.abs(n)<.5*10**(-d)?0:n).toLocaleString('de-DE',{minimumFractionDigits:d,maximumFractionDigits:d});const positive=n=>(n>0?'+':'')+fmt(n)+' %';const colors=['var(--chart-1,#4189de)','var(--chart-2,#ed9937)','var(--chart-3,#bc62a3)'];
function update(){const country=document.getElementById('country').value,series=country==='all'?data.total:data.countries.find(c=>c.country===country).series,last=series.at(-1),metric=document.getElementById('metric').value;document.getElementById('stats').innerHTML='<div><b>'+positive(last.qualityPct)+'</b><span>Stärke nach Saison '+last.season+'</span></div><div><b>'+fmt(last.closingPlayers)+'</b><span>Spieler nach Abschieden</span></div><div><b>'+fmt(last.expenses,0)+'</b><span>Credits / Verein im letzten Jahr</span></div>';const settings={quality:{keys:['qualityPct','controlQualityPct'],labels:['Mit Karriereenden','Bisherige Regeln'],unit:'%',note:'Mittlere Kaderqualität je Verein. Die Vergleichswelten verwenden denselben Quellstand und dieselben Seeds.'},players:{keys:['openingPlayers','closingPlayers'],labels:['Nach dem Transferfenster','Nach Abschieden'],unit:'Spieler',note:'Eine Lücke nach Saisonabschluss ist noch kein Ausfall im Spielbetrieb. Maßgeblich ist die Auffüllung vor dem folgenden Transferfensterende.'},costs:{keys:['expenses','salaries','youthFunding'],labels:['Gesamtausgaben','Gehälter','Jugendförderung'],unit:'Credits',note:'Bruttoausgaben je Verein. Gesamtausgaben enthalten Förderung, Übernahmen, Ablösen und sonstige Belastungen; Einnahmen sind nicht gegengerechnet.'},youth:{keys:['generated','promoted'],labels:['Neu erzeugt','In Profikader übernommen'],unit:'Spieler',note:'Neue Kandidaten je Saison, ohne den anfänglichen Jahrgang Y0. Übernahmen können Kandidaten aus mehreren Jahrgängen betreffen.'}}[metric];const width=Math.max(300,document.getElementById('chart').clientWidth);document.getElementById('chart').setAttribute('viewBox','0 0 '+width+' 260');const values=series.flatMap(r=>settings.keys.map(k=>r[k])),min=Math.min(0,...values),max=Math.max(...values)*1.08||1,x=n=>48+(n-1)*(width-70)/Math.max(1,data.latest-1),y=n=>225-(n-min)*195/(max-min||1);let svg='';for(let i=0;i<5;i++){const n=min+(max-min)*i/4;svg+='<line x1="48" x2="'+(width-20)+'" y1="'+y(n)+'" y2="'+y(n)+'" stroke="var(--border,#ddd)"/><text x="42" y="'+(y(n)+4)+'" text-anchor="end" fill="var(--muted-foreground,#667)" font-size="10">'+fmt(n,metric==='costs'?0:1)+'</text>';}for(const n of [...new Set([1,5,10,15,data.latest])].filter(n=>n<=data.latest))svg+='<text x="'+x(n)+'" y="248" text-anchor="middle" fill="var(--muted-foreground,#667)" font-size="11">'+n+'</text>';settings.keys.forEach((k,i)=>{svg+='<path d="'+series.map((r,j)=>(j?'L':'M')+x(r.season)+','+y(r[k])).join(' ')+'" fill="none" stroke="'+colors[i]+'" stroke-width="2.5"/>';for(const r of series)svg+='<circle cx="'+x(r.season)+'" cy="'+y(r[k])+'" r="3.5" fill="'+colors[i]+'"><title>Saison '+r.season+': '+settings.labels[i]+' '+fmt(r[k])+' '+settings.unit+'</title></circle>';});document.getElementById('chart').innerHTML=svg;document.getElementById('legend').innerHTML=settings.labels.map((l,i)=>'<span><i style="background:'+colors[i]+'"></i>'+l+'</span>').join('');document.getElementById('note').textContent=settings.note;document.getElementById('rows').innerHTML=series.map(r=>'<tr><td>'+r.season+'</td><td>'+positive(r.qualityPct)+'</td><td>'+fmt(r.openingPlayers)+' → '+fmt(r.closingPlayers)+'</td><td>'+fmt(r.expenses,0)+'</td><td>'+fmt(r.salaries,0)+'</td><td>'+fmt(r.youthFunding,0)+'</td><td>'+fmt(r.generated)+'</td><td>'+fmt(r.promoted)+'</td><td>'+fmt(r.retired)+'</td></tr>').join('');}
document.getElementById('country').addEventListener('change',update);document.getElementById('metric').addEventListener('change',update);window.addEventListener('resize',update);update();console.log('Dashboard:',data.latest,'Saisons,',data.countries.length,'Länder');</script></body></html>`;
fs.writeFileSync(path.join(out,'report.html'),html);console.log('Wrote dashboard',html.length);
